import "cubie_cube.dart";
import "moves.dart";

/// The 16 symmetries of the cube that fix the U/D axis, generated by S_F2,
/// S_U4 and S_LR2.
///
/// These are what makes min2phase's tables small: two states related by a
/// symmetry need the same number of moves to solve, so the coordinate tables
/// only have to store one representative per equivalence class. That turns the
/// 2187 twist coordinates into 324 classes and the 40320 edge permutations into
/// 2768.
///
/// S_LR2 is a mirror, so the symmetry cubes use the mirrored corner
/// orientations 3..5 that [CubieCube.cornerMultiply] handles.
final List<CubieCube> cubeSym = _initSym();

/// `symMult[i][j]` is the index of `cubeSym[i] * cubeSym[j]`.
final List<List<int>> symMult = _initSymMult();

/// `symInv[i]` is the index of the inverse of `cubeSym[i]`.
final List<int> symInv = _initSymInv();

/// `symMove[s][m]` is the move that `cubeSym[s]` turns move `m` into.
///
/// Conjugating a face turn by one of these symmetries always yields another
/// face turn, which is what lets a search work in the reduced coordinate space.
final List<List<int>> symMove = _initSymMove();

const int symCount = 16;

/// Raw `(cperm, twist, eperm, flip)` coordinates of the three generators.
const (int, int, int, int) _f2 = (28783, 0, 259268407, 0);
const (int, int, int, int) _u4 = (15138, 0, 119765538, 7);
const (int, int, int, int) _lr2 = (5167, 0, 83473207, 0);

CubieCube _fromTuple((int, int, int, int) t) =>
    CubieCube.fromCoordinates(cperm: t.$1, twist: t.$2, eperm: t.$3, flip: t.$4);

List<CubieCube> _initSym() {
  final f2 = _fromTuple(_f2);
  final u4 = _fromTuple(_u4);
  final lr2 = _fromTuple(_lr2);
  // S_LR2 mirrors the cube, so every corner carries the mirror flag.
  for (var i = 0; i < CubieCube.cornerLength; i++) {
    lr2.cornerState[i] |= 3 << 3;
  }

  final syms = <CubieCube>[];
  final c = CubieCube();
  for (var i = 0; i < symCount; i++) {
    syms.add(CubieCube.from(c));
    c.multiply(u4);
    if (i % 4 == 3) {
      c.multiply(lr2);
    }
    if (i % 8 == 7) {
      c.multiply(f2);
    }
  }

  return syms;
}

bool _sameState(CubieCube a, CubieCube b) {
  for (var i = 0; i < CubieCube.cornerLength; i++) {
    if (a.cornerState[i] != b.cornerState[i]) return false;
  }
  for (var i = 0; i < CubieCube.edgeLength; i++) {
    if (a.edgeState[i] != b.edgeState[i]) return false;
  }
  return true;
}

int _indexOfSym(CubieCube c) {
  for (var i = 0; i < symCount; i++) {
    if (_sameState(cubeSym[i], c)) return i;
  }
  throw StateError("Cube is not one of the 16 symmetries");
}

List<List<int>> _initSymMult() {
  return List.generate(symCount, (j) {
    return List.generate(symCount, (k) {
      final product = CubieCube.from(cubeSym[j]);
      product.multiply(cubeSym[k]);
      return _indexOfSym(product);
    });
  });
}

List<int> _initSymInv() {
  return List.generate(symCount, (j) {
    for (var k = 0; k < symCount; k++) {
      if (symMult[j][k] == 0) return k;
    }
    throw StateError("Symmetry $j has no inverse");
  });
}

/// `cubeSym[symInv[idx]] * a * cubeSym[idx]`.
///
/// min2phase fuses this into a single loop; composing twice is slower but only
/// runs while the tables are being built.
CubieCube conjugate(CubieCube a, int idx) {
  final result = CubieCube.from(cubeSym[symInv[idx]]);
  result.multiply(a);
  result.multiply(cubeSym[idx]);
  return result;
}

List<List<int>> _initSymMove() {
  return List.generate(symCount, (s) {
    return List.generate(moveCube.length, (m) {
      final conjugated = conjugate(moveCube[m], symInv[s]);
      for (var candidate = 0; candidate < moveCube.length; candidate++) {
        if (_sameState(moveCube[candidate], conjugated)) return candidate;
      }
      throw StateError("Conjugating move $m by symmetry $s did not yield a face turn");
    });
  });
}

/// S_URF: the order 3 rotation about the URF-DBL body diagonal, which cycles
/// the U, R and F axes.
///
/// This one is deliberately **not** in [cubeSym]. Those 16 all fix the U/D
/// axis, which is what the phase 1 and phase 2 coordinates are defined around;
/// S_URF moves that axis, so it cannot be used to reduce those tables. What it
/// is good for is running the search three times over, once per axis: a cube
/// that needs many moves to reach the phase 2 subgroup one way round often
/// needs far fewer another way, and taking the best of three is most of what
/// makes min2phase quick.
final CubieCube urf1 = CubieCube.fromCoordinates(
  cperm: 2531,
  twist: 1373,
  eperm: 67026819,
  flip: 1367,
);

/// The inverse of [urf1], equal to `urf1 * urf1`.
final CubieCube urf2 = CubieCube.fromCoordinates(
  cperm: 2089,
  twist: 1906,
  eperm: 322752913,
  flip: 2040,
);

/// `urf2 * a * urf1`, the cube seen with the axes rotated once.
CubieCube urfConjugate(CubieCube a) {
  final result = CubieCube.from(urf2);
  result.multiply(a);
  result.multiply(urf1);
  return result;
}

/// `urfMove[m]` is the move that [urfConjugate] turns move `m` into.
final List<int> urfMove = _initUrfMove();

List<int> _initUrfMove() {
  return List.generate(moveCube.length, (m) {
    final conjugated = urfConjugate(moveCube[m]);
    for (var candidate = 0; candidate < moveCube.length; candidate++) {
      if (_sameState(moveCube[candidate], conjugated)) return candidate;
    }
    throw StateError("Conjugating move $m by S_URF did not yield a face turn");
  });
}
